// Analyze workflow runs for DORA metrics
const runs = $input.all().map(n => n.json).flatMap(n => n.workflow_runs || []);

const now = new Date();
const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const recentRuns = runs.filter(r => new Date(r.created_at) > lastWeek);
const deployments = recentRuns.filter(r => r.conclusion === 'success').length;
const failed = recentRuns.filter(r => r.conclusion === 'failure').length;

const totalTime = recentRuns.reduce((sum, r) => sum + (r.run_duration_ms || 0), 0);
const avgDurationMin = totalTime / (recentRuns.length || 1) / 60000;

// Flaky: runs with same workflow+job but different conclusion
const runMap = {};
recentRuns.forEach(r => {
  const key = `${r.name}_${r.run_attempt}`;
  if (!runMap[key]) runMap[key] = [];
  runMap[key].push(r.conclusion);
});
const flakyCount = Object.values(runMap).filter(cs => cs.length > 1 && new Set(cs).size > 1).length;

return [{ json: {
  deployments,
  failed,
  changeFailureRate: recentRuns.length > 0 ? (failed / recentRuns.length * 100).toFixed(1) : '0',
  avgDurationMin: avgDurationMin.toFixed(1),
  flakyTests: flakyCount,
  totalRuns: recentRuns.length,
  checkedAt: now.toISOString()
}}];

